ALTER TABLE public.plans ADD CONSTRAINT plans_user_week_unique UNIQUE (user_id, week_start);
CREATE OR REPLACE FUNCTION public.save_week_plan(p_week date, p_answers jsonb, p_plan jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY INVOKER SET search_path = public AS $$ DECLARE ci_id uuid; plan_id uuid; BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; INSERT INTO public.check_ins (week_start, answers) VALUES (p_week, p_answers) RETURNING id INTO ci_id; INSERT INTO public.plans (user_id, week_start, check_in_id, plan_json, locked) VALUES (auth.uid(), p_week, ci_id, p_plan, '[]'::jsonb) ON CONFLICT (user_id, week_start) DO UPDATE SET check_in_id = EXCLUDED.check_in_id, plan_json = EXCLUDED.plan_json, locked = '[]'::jsonb, created_at = now() RETURNING id INTO plan_id; DELETE FROM public.grocery_lists WHERE grocery_lists.plan_id = save_week_plan.plan_id; RETURN plan_id; END; $$;
REVOKE ALL ON FUNCTION public.save_week_plan(date,jsonb,jsonb) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.save_week_plan(date,jsonb,jsonb) TO authenticated, service_role;